contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: deposit some funds (optional) and then try CashOut
    // params: depositAmt to deposit into c (may be 0), withdrawAmt to attempt to withdraw
    function run(uint depositAmt, uint withdrawAmt) public payable {
        require(address(this).balance >= depositAmt, "need funds to deposit");

        // Record before values
        uint beforeBal = c.balances(address(this));
        uint beforeContractEth = address(c).balance;
        uint beforeThisEth = address(this).balance;

        // If depositAmt >= MinDeposit of c then Deposit will increase balances; else it will be ignored.
        // Make the deposit call (may be zero)
        if (depositAmt > 0) {
            c.Deposit{value: depositAmt}();
        }

        // Record mid-state after deposit
        uint midBal = c.balances(address(this));
        uint midContractEth = address(c).balance;
        uint midThisEth = address(this).balance;

        // Attempt CashOut and catch whether it reverted
        bool reverted;
        // CashOut is non-payable; must call directly and catch revert
        try c.CashOut(withdrawAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record after values
        uint afterBal = c.balances(address(this));
        uint afterContractEth = address(c).balance;
        uint afterThisEth = address(this).balance;

        // General rule:
        // - If CashOut reverted then balances and contract balances remain equal to mid-state
        // - If CashOut succeeded then balances decreased by withdrawAmt and contract ether decreased by withdrawAmt
        // Note: reading public getters only and address balances
        assert(
            (reverted && afterBal == midBal && afterContractEth == midContractEth && afterThisEth == midThisEth)
            || (!reverted && afterBal + withdrawAmt == midBal && afterContractEth + withdrawAmt == midContractEth && afterThisEth == midThisEth + withdrawAmt)
        );
    }

    // allow receiving Ether for deposits and refunds
    receive() external payable {}
}

