contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint depositAmount, uint cashAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // ensure deposit meets MinDeposit to be accepted by c
        // read MinDeposit via public getter
        uint minD = c.MinDeposit();
        // if depositAmount is too small, adjust by requiring it's >= minD
        require(depositAmount >= minD, "deposit must be >= MinDeposit");

        // Deposit into c: this will increase c.balances(this) if accepted
        c.Deposit{value: depositAmount}();

        // record balances before cashout
        uint beforeUserBal = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // attempt CashOut and record whether it reverted
        bool reverted;
        try c.CashOut(cashAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint afterUserBal = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // General rule/assertion:
        // 1) c.balances for this contract never increases due to CashOut call
        // 2) if CashOut did not revert then the balances decreased by exactly cashAmount
        //    and the contract Ether balance decreased by exactly cashAmount
        assert(
            // balances never increased
            afterUserBal <= beforeUserBal
            && (
                // either reverted: then balances and contract balance unchanged
                (reverted && afterUserBal == beforeUserBal && afterContractBal == beforeContractBal)
                ||
                // or not reverted: then decreased exactly by cashAmount (but not underflowed)
                (!reverted && beforeUserBal >= cashAmount && afterUserBal == (beforeUserBal - cashAmount)
                    && beforeContractBal >= cashAmount && afterContractBal == (beforeContractBal - cashAmount))
            )
        );
    }

    // Allow this contract to receive Ether when c sends funds
    receive() external payable {}
}

