contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to cash out `amt`. The test contract must hold enough balance to
    // cover any pre-deposits we make; we will optionally deposit first.
    function run(uint preDeposit, uint amt) public payable {
        require(address(this).balance >= preDeposit, "insufficient test balance for preDeposit");

        // If we want the test contract to have some recorded balance, deposit preDeposit.
        // Read MinDeposit to know whether Deposit will accept the preDeposit.
        uint minD = c.MinDeposit();

        uint beforeRecorded = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        if (preDeposit >= minD) {
            // send Ether to Deposit to increase recorded balance
            c.Deposit{value: preDeposit}();
        } else if (preDeposit > 0) {
            // deposit below min is ignored by C; still perform the call to exercise behavior
            c.Deposit{value: preDeposit}();
        }

        // Read values after optional deposit and before CashOut
        uint recordedBeforeCash = c.balances(address(this));
        uint contractBalBeforeCash = address(c).balance;

        // Try to CashOut amt and capture whether it reverted
        bool reverted;
        try c.CashOut(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read values after CashOut attempt
        uint recordedAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;

        // General invariant to assert:
        // 1) recorded balance never increases as a result of CashOut attempt
        // 2) If CashOut did not revert then it must have been the case that amt <= recordedBeforeCash,
        //    recordedAfter == recordedBeforeCash - amt, and contractBalAfter == contractBalBeforeCash - amt.
        // 3) If CashOut reverted then recorded and contract balances must be unchanged.
        assert(
            // recorded never increases
            recordedAfter <= recordedBeforeCash
            // two cases: success (not reverted) or reverted
            && (
                (!reverted
                    && amt <= recordedBeforeCash
                    && recordedAfter == recordedBeforeCash - amt
                    && contractBalAfter == contractBalBeforeCash - amt
                )
                || (reverted
                    && recordedAfter == recordedBeforeCash
                    && contractBalAfter == contractBalBeforeCash
                )
            )
        );
    }

    receive() external payable {}
}

