contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to Deposit some amount (maybe zero if below MinDeposit) and then attempts CashOut.
    // params:
    //  - depositAmt: amount of wei to send to c.Deposit()
    //  - cashAmt: amount of wei to request via c.CashOut(cashAmt)
    function run(uint depositAmt, uint cashAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // Record initial observable values
        uint before_c_balance = address(c).balance;
        uint before_my_bal = c.balances(address(this));

        // Perform deposit: use value from parameter
        if (depositAmt > 0) {
            // call Deposit with value depositAmt
            c.Deposit{value: depositAmt}();
        }

        // After deposit readings
        uint after_deposit_c_balance = address(c).balance;
        uint after_deposit_my_bal = c.balances(address(this));

        // Attempt CashOut and capture whether it reverted
        bool reverted;
        try c.CashOut(cashAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Final observable values
        uint final_c_balance = address(c).balance;
        uint final_my_bal = c.balances(address(this));
        uint my_received = address(this).balance; // this contract's balance may increase when CashOut succeeds

        // General invariant to assert:
        // 1) balances[address(this)] is never greater than the c contract's balance (i.e., c holds at least the sum of all recorded balances for this address)
        // 2) balances never underflows: final_my_bal <= after_deposit_my_bal and if CashOut succeeded then after_deposit_my_bal - final_my_bal == cashAmt
        // 3) if CashOut succeeded then c's on-chain balance decreased by cashAmt
        // Combine into one assert expression over observed values and reverted flag.
        assert(
            // c holds at least the recorded per-address balance for this address at the end
            final_c_balance >= final_my_bal
            // balances did not increase unexpectedly beyond what deposit did
            && final_my_bal <= after_deposit_my_bal
            // If CashOut succeeded then balances decreased exactly by cashAmt and contract balance decreased by cashAmt
            && (reverted || (after_deposit_my_bal >= final_my_bal && (after_deposit_my_bal - final_my_bal == cashAmt) && (after_deposit_c_balance >= final_c_balance) && (after_deposit_c_balance - final_c_balance == cashAmt)))
        );
    }

    // allow receiving Ether when c sends funds via call
    receive() external payable {}
}

contract InvMutTest {
