    // Attempt to deposit then cash out. Parameters:
    // depositAmt: wei to send with Deposit()
    // cashAmt: amount to request via CashOut(cashAmt)
    function run(uint depositAmt, uint cashAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // Observables before any interaction
        uint before_c_balance = address(c).balance;
        uint before_my_recorded = c.balances(address(this));

        // Perform Deposit if any amount is provided
        if (depositAmt > 0) {
            c.Deposit{value: depositAmt}();
        }

        // Observables after deposit
        uint after_deposit_c_balance = address(c).balance;
        uint after_deposit_my_recorded = c.balances(address(this));

        // Attempt CashOut and record whether it reverted
        bool reverted;
        try c.CashOut(cashAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after CashOut attempt
        uint final_c_balance = address(c).balance;
        uint final_my_recorded = c.balances(address(this));

        // If CashOut succeeded then both the contract's on-chain balance and the recorded balance for this address
        // must have decreased by exactly cashAmt. If it reverted then neither observable should have decreased due to CashOut.
        // Note: Deposit could have changed balances earlier; we compare post-deposit -> final to isolate CashOut effect.
        assert(
            (!reverted && after_deposit_my_recorded >= final_my_recorded && after_deposit_c_balance >= final_c_balance &&
