contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositor is this contract (invoker), amount is attempted deposit
    function run(uint amount) public payable {
        // Ensure this contract has enough Ether to forward the deposit amount
        require(address(this).balance >= amount, "insufficient test balance");

        // Read before-values via public getters
        uint before_balance_of_this = c.balances(address(this));
        uint before_contract_balance = address(c).balance;
        uint minDeposit = c.MinDeposit();

        bool reverted = false;
        // Make the deposit call as a top-level statement, forwarding `amount` wei
        // Deposit may revert only due to internal require/checks; catch to record
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint after_balance_of_this = c.balances(address(this));
        uint after_contract_balance = address(c).balance;

        // General rule:
        // If amount >= minDeposit then Deposit must not revert, and both the public balances entry
        // and the contract's Ether balance increase by exactly amount.
        // If amount < minDeposit then Deposit must not change balances or contract balance (and not revert).
        // (Note: The provided contract's Deposit implementation never reverts except on overflow check
        // which is impossible here due to require on balance addition; we still track reverted flag.)
        assert(
            // Case A: amount >= minDeposit
            (
                amount >= minDeposit
                && reverted == false
                && after_balance_of_this == before_balance_of_this + amount
                && after_contract_balance == before_contract_balance + amount
            )
            // Case B: amount < minDeposit
            || (
                amount < minDeposit
                && reverted == false
                && after_balance_of_this == before_balance_of_this
                && after_contract_balance == before_contract_balance
            )
        );
    }

    // Allow the test contract to receive Ether so it can forward deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: initialDeposit (we will deposit from this test to ensure caller has funds), withdrawAmt
    function run(uint initialDeposit, uint withdrawAmt) public payable {
        // ensure this test contract has funds to make the initial deposit
        require(address(this).balance >= initialDeposit, "insufficient test balance");

        // Read MinDeposit to decide whether Deposit will be accepted
        uint minD = c.MinDeposit();

        // Record before-values
        uint before_contract_balance = address(c).balance;
        uint before_balance_of_this = c.balances(address(this));

        // Make a deposit attempt (top-level statement). This may be ignored if < MinDeposit.
        bool dep_reverted;
        try c.Deposit{value: initialDeposit}() {
            dep_reverted = false;
        } catch {
            dep_reverted = true;
        }

        // Read after deposit values
        uint after_balance_of_this = c.balances(address(this));
        uint after_contract_balance = address(c).balance;

        // Now attempt CashOut(withdrawAmt) as the caller (this contract)
        bool co_reverted;
        try c.CashOut(withdrawAmt) {
            co_reverted = false;
        } catch {
            co_reverted = true;
        }

        // Read final values
        uint final_balance_of_this = c.balances(address(this));
        uint final_contract_balance = address(c).balance;

        // Assert the invariant describing valid CashOut behavior for all inputs:
        // 1) CashOut never increases the contract's Ether balance.
        // 2) CashOut never increases the caller's recorded public balances.
        // 3) If CashOut succeeded (did not revert), then caller's public balance decreased by withdrawAmt
        //    and contract balance decreased by withdrawAmt (i.e. transferred out).
        // 4) If CashOut reverted then balances remain unchanged by the CashOut call.
        assert(
            // 1 & 2: final balances are not greater than before CashOut
            final_contract_balance <= after_contract_balance
            && final_balance_of_this <= after_balance_of_this
            && (
                // If CashOut succeeded: amounts decreased exactly by withdrawAmt
                (co_reverted == false
                    && after_balance_of_this >= withdrawAmt
                    && final_balance_of_this == after_balance_of_this - withdrawAmt
                    && after_contract_balance >= withdrawAmt
                    && final_contract_balance == after_contract_balance - withdrawAmt)
                // If CashOut reverted: no change
                || (co_reverted == true
                    && final_balance_of_this == after_balance_of_this
                    && final_contract_balance == after_contract_balance)
            )
        );
    }

    // allow receiving Ether from C during CashOut
    receive() external payable {}
}

